  client.deliver(hostEnvelope('hello_ack', {}));

  window.dispatchEvent(new Event('pagehide'));
  expect(envelopes.at(-1)?.type).toBe('page_hidden');

  const restored = new Event('pageshow');
  Object.defineProperty(restored, 'persisted', { value: true });
  window.dispatchEvent(restored);
  client.send('state_request', {});
  expect(envelopes.slice(-2).map((e) => e.type)).toEqual(['hello', 'state_request']);
  // The chat stays on screen while the host answers.
  expect(states.at(-1)?.state).toBe('connected');

  const firstLoad = new Event('pageshow');
  Object.defineProperty(firstLoad, 'persisted', { value: false });
  window.dispatchEvent(firstLoad);
  expect(envelopes.filter((e) => e.type === 'hello')).toHaveLength(2);
});

it('assigns unique page envelope IDs', () => {

input.old_string:
SECTION("messages before hello get handshake_required") {
    harness.deliver("state_request");
    const json* error = harness.last_of_type("bridge_error");
    REQUIRE(error != nullptr);
    CHECK((*error)["payload"]["code"] == "handshake_required");
}

input.new_string:
SECTION("messages before hello get handshake_required") {
    harness.deliver("state_request");
    const json* error = harness.last_of_type("bridge_error");
    REQUIRE(error != nullptr);
    CHECK((*error)["payload"]["code"] == "handshake_required");
}

// The page says when its document goes; a navigation the web view merely
// starts no longer ends the handshake, since the page may stay.
SECTION("a page that says it is going must shake hands again") {
    harness.handshake();
    harness.deliver("page_hidden");
    REQUIRE_FALSE(harness.host.handshake_complete());
    CHECK(harness.last_of_type("bridge_error") == nullptr);

    harness.deliver("state_request");
    const json* error = harness.last_of_type("bridge_error");
    REQUIRE(error != nullptr);
    CHECK((*error)["payload"]["code"] == "handshake_required");

    harness.handshake();
    const std::size_t before = harness.of_type("state").size();
    harness.deliver("state_request");
    CHECK(harness.of_type("state").size() == before + 1);
}
